<template><div class="app-container"><el-form v-show="showSearch" :inline="true" size="small" :model="query" ref="query"><el-form-item label="分类名称"><el-input v-model="query.categoryName" clearable @keyup.enter.native="load" /></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="正常" value="0"/><el-option label="停用" value="1"/></el-select></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" size="mini" @click="load">查询</el-button><el-button icon="el-icon-refresh" size="mini" @click="reset">重置</el-button></el-form-item></el-form><el-row class="mb8"><el-button type="primary" plain icon="el-icon-plus" size="mini" @click="openAdd" v-hasPermi="['mall:category:add']">新增</el-button><right-toolbar :showSearch.sync="showSearch" @queryTable="load"/></el-row><el-table v-loading="loading" :data="list"><el-table-column prop="categoryId" label="编号" width="80"/><el-table-column prop="categoryName" label="分类名称"/><el-table-column prop="parentId" label="父分类" width="90"/><el-table-column prop="level" label="层级" width="70"/><el-table-column prop="sortNo" label="排序" width="70"/><el-table-column label="状态" width="90"><template slot-scope="s"><el-tag :type="s.row.status === '0' ? 'success' : 'info'">{{ s.row.status === '0' ? '正常' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template slot-scope="s"><el-button type="text" size="mini" icon="el-icon-edit" @click="openEdit(s.row)" v-hasPermi="['mall:category:edit']">修改</el-button><el-button type="text" size="mini" icon="el-icon-delete" @click="remove(s.row)" v-hasPermi="['mall:category:remove']">删除</el-button></template></el-table-column></el-table><el-dialog :title="title" :visible.sync="dialog" width="500px"><el-form ref="form" :model="form" label-width="90px"><el-form-item label="分类名称" required><el-input v-model="form.categoryName"/></el-form-item><el-form-item label="父分类"><el-input-number v-model="form.parentId" :min="0"/></el-form-item><el-form-item label="层级"><el-input-number v-model="form.level" :min="1"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortNo" :min="0"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio label="0">正常</el-radio><el-radio label="1">停用</el-radio></el-radio-group></el-form-item></el-form><div slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">确定</el-button></div></el-dialog></div></template>
<script>import { listCategories, addCategory, updateCategory, delCategory } from '@/api/mall/catalog'
export default { name: 'MallCategory', data () { return { showSearch: true, loading: false, list: [], query: {}, dialog: false, title: '', form: {} } }, created () { this.load() }, methods: { load () { this.loading = true; listCategories(this.query).then(r => { this.list = r.data || [] }).finally(() => { this.loading = false }) }, reset () { this.query = {}; this.load() }, openAdd () { this.title = '新增分类'; this.form = { parentId: 0, level: 1, sortNo: 0, status: '0' }; this.dialog = true }, openEdit (row) { this.title = '修改分类'; this.form = Object.assign({}, row); this.dialog = true }, save () { if (!this.form.categoryName) return this.$modal.msgError('请输入分类名称'); const fn = this.form.categoryId ? updateCategory : addCategory; fn(this.form).then(() => { this.$modal.msgSuccess('保存成功'); this.dialog = false; this.load() }) }, remove (row) { this.$modal.confirm('确认删除该分类？').then(() => delCategory(row.categoryId)).then(() => { this.$modal.msgSuccess('删除成功'); this.load() }).catch(() => {}) } } }</script>
